 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def spans(length, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < length:
            result.append((start, length))
        return result

    rows, cols = spans(h, sep_rows), spans(w, sep_cols)
    nr, nc = len(rows), len(cols)
    markers = {}
    panel_color = {}
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            if colors:
                panel_color[(ri, ci)] = min(colors)
                for color in colors:
                    markers.setdefault(color, set()).add((ri, ci))

    # Two or more same-colored markers in a panel row/column bridge the
    # inclusive span between them. Intersections combine the stripe colors.
    row_lines, col_lines = {}, {}
    for color, pts in markers.items():
        for ri in range(nr):
            cset = sorted({ci for r, ci in pts if r == ri})
            if len(cset) >= 2:
                for ci in range(cset[0], cset[-1] + 1):
                    row_lines.setdefault((ri, ci), set()).add(color)
        for ci in range(nc):
            rset = sorted({ri for ri, c in pts if c == ci})
            if len(rset) >= 2:
                for ri in range(rset[0], rset[-1] + 1):
                    col_lines.setdefault((ri, ci), set()).add(color)

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            colors = row_lines.get((ri, ci), set()) | col_lines.get((ri, ci), set())
            if (ri, ci) in panel_color:
                colors = colors | {panel_color[(ri, ci)]}
            if colors:
                color = 1
                for value in colors:
                    color *= value
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out
